# Generated by clisage integration bash. Requires Bash 4+ with Readline.
# Only an explicit Alt-G sends the current input line to the provider.
_clisage_bash_widget() {
    local suggestion
    [[ -n ${READLINE_LINE//[[:space:]]/} ]] || return 0
    printf '\nClisage: generating a command suggestion...\n' >&2
    if suggestion=$(command clisage shell --command-only -- "$READLINE_LINE" </dev/null); then
        if [[ -n $suggestion ]]; then
            READLINE_LINE=$suggestion
            # Readline cursor offsets count bytes, including in UTF-8 locales.
            local LC_ALL=C
            READLINE_POINT=${#READLINE_LINE}
        else
            printf 'Clisage: empty suggestion; original input kept.\n' >&2
        fi
    else
        printf 'Clisage: request failed or cancelled; original input kept.\n' >&2
    fi
    # Assigning READLINE_LINE never accepts or executes the line.
    return 0
}
if [[ $- == *i* ]]; then
    if (( BASH_VERSINFO[0] < 4 )); then
        printf 'Clisage Alt-G integration requires Bash 4+ or Zsh.\n' >&2
    else
        bind -m emacs-standard -x '"\eg":_clisage_bash_widget'
        bind -m emacs-standard -x '"\eG":_clisage_bash_widget'
        bind -m vi-insert -x '"\eg":_clisage_bash_widget'
        bind -m vi-insert -x '"\eG":_clisage_bash_widget'
    fi
fi
